changeSet.sql:
CREATE TABLE stored_files ( id uuid NOT NULL PRIMARY KEY, tenant_id uuid REFERENCES organizations (id), branch_id uuid, created_at timestamp(6) with time zone NOT NULL, updated_at timestamp(6) with time zone, created_by varchar(255), updated_by varchar(255), deleted boolean NOT NULL,
visibility varchar(8) NOT NULL, bucket varchar(63) NOT NULL, object_key varchar(255) NOT NULL, purpose varchar(40) NOT NULL, file_name varchar(255) NOT NULL, file_type varchar(8) NOT NULL, size_bytes bigint NOT NULL, status varchar(10) NOT NULL, uploaded_by uuid NOT NULL REFERENCES users (id), upload_link_expires_at timestamp(6) with time zone NOT NULL, confirmed_at timestamp(6) with time zone, removed_at timestamp(6) with time zone,
CONSTRAINT chk_stored_files_visibility CHECK (visibility IN ('PUBLIC', 'PRIVATE')), CONSTRAINT chk_stored_files_file_type CHECK (file_type IN ('JPEG', 'PNG', 'WEBP', 'PDF')), CONSTRAINT chk_stored_files_status CHECK (status IN ('PENDING', 'READY', 'REJECTED', 'EXPIRED', 'DELETED')), CONSTRAINT chk_stored_files_size_positive CHECK (size_bytes > 0), CONSTRAINT chk_stored_files_confirmed_when_ready CHECK (status <> 'READY' OR confirmed_at IS NOT NULL), CONSTRAINT uq_stored_files_bucket_key UNIQUE (bucket, object_key) ); CREATE INDEX idx_stored_files_status_created ON stored_files (status, created_at); REVOKE DELETE, TRUNCATE ON stored_files FROM ${appDbUsername}; COMMENT ON TABLE stored_files IS 'Files uploaded to object storage (the bytes live there). One row per upload, never deleted. Not RLS-policied: reached by id, acted on only by the uploader unless the owning module decides otherwise. See AGENTS.md, "File storage".'; COMMENT ON COLUMN stored_files.file_type IS 'Checked from the file''s first bytes at confirmation, never trusted from the uploader.';
